// Generated by deno-lifeboat. A minimal Deno.TestContext for test runners without subtests (bun:test, vitest).
// Steps run inline, in order, like awaited `t.step()` calls in Deno; they are not reported separately.

type StepFn = (t: TestContext) => void | Promise<void>;

interface StepDefinition {
  name: string;
  fn: StepFn;
  ignore?: boolean;
}

export interface TestContext {
  readonly name: string;
  readonly parent?: TestContext;
  step(definition: StepDefinition): Promise<boolean>;
  step(name: string, fn: StepFn): Promise<boolean>;
  step(fn: StepFn): Promise<boolean>;
}

export function testContext(name: string, parent?: TestContext): TestContext {
  const context: TestContext = {
    name,
    parent,
    async step(first: StepDefinition | string | StepFn, second?: StepFn): Promise<boolean> {
      const definition: StepDefinition =
        typeof first === "function"
          ? { name: first.name || "step", fn: first }
          : typeof first === "string"
            ? { name: first, fn: second as StepFn }
            : first;
      if (definition.ignore) return false;
      await definition.fn(testContext(definition.name, context));
      return true;
    },
  };
  return context;
}
